content.content:
{
	"$schema": "https://biomejs.dev/schemas/2.6.6/schema.json",
	"vcs": {
		"enabled": true,
		"clientKind": "git",
		"useIgnoreFile": true
	},
	"files": {
		"ignoreUnknown": true,
		"includes": ["**", "!!.sanity"]
	},
	"overrides": [
		{
			"includes": ["sanity/plugins/help/articles.generated.json"],
			"formatter": {
				"enabled": false
			}
		}
	],
	"formatter": {
		"enabled": true,
		"indentStyle": "tab",
		"indentWidth": 2
	},
	"linter": {
		"enabled": true,
		"rules": {
			"preset": "recommended",
			"a11y": {
				"preset": "recommended"
			},
			"complexity": {
				"preset": "recommended"
			},
			"correctness": {
				"preset": "recommended",
				"useExhaustiveDependencies": "error"
			},
			"nursery": {
				"preset": "none"
			},
			"style": {
				"preset": "recommended"
			},
			"suspicious": {
				"preset": "recommended"
			}
		}
	},
	"javascript": {
		"formatter": {
			"quoteStyle": "single",
			"jsxQuoteStyle": "double",
			"semicolons": "asNeeded"
		}
	},
	"json": {
		"formatter": {
			"indentWidth": 2
		}
	},
	"markdown": {
		"formatter": {
			"enabled": false
		}
	},
	"assist": {
		"enabled": true,
		"actions": {
			"source": {
				"organizeImports": "on"
			}
		}
	}
}

